#!/usr/bin/env bash
set -Eeuo pipefail
ssh_args() { SSH_ARGS=(-p "$PRODUCTION_SSH_PORT"); [ -n "$PRODUCTION_SSH_IDENTITY_FILE" ] && SSH_ARGS=("${SSH_ARGS[@]}" -i "$PRODUCTION_SSH_IDENTITY_FILE"); SSH_ARGS=("${SSH_ARGS[@]}" -o BatchMode=no -o StrictHostKeyChecking=accept-new "$PRODUCTION_SSH_USER@$PRODUCTION_SSH_HOST"); }
remote_exec() { ssh_args; if [ "${VERBOSE:-0}" -eq 1 ]; then info "remote command: $1"; fi; ssh "${SSH_ARGS[@]}" "bash -lc $(shell_quote "$1")"; }
wp_remote() { remote_exec "cd $(shell_quote "$PRODUCTION_ROOT") && $REMOTE_WP_COMMAND $*"; }
remote_value() { wp_remote "$@" | tail -n 1 | tr -d '\r'; }
discover_remote_roots() { local candidates; candidates=$(remote_exec 'for d in "$HOME"/domains/*/public_html; do test -f "$d/wp-config.php" && printf "%s\n" "$d"; done' 2>/dev/null) || { warn 'could not discover Hostinger WordPress roots; enter the exact absolute path'; return; }; if [ -n "$candidates" ]; then info 'Hostinger WordPress root candidates:'; printf '%s\n' "$candidates" >&2; else warn 'no wp-config.php candidates found under ~/domains/*/public_html'; fi; }
verify_remote_target() { PHASE=remote-safety; ssh_args; ssh "${SSH_ARGS[@]}" true >/dev/null || die 4 'cannot connect to configured SSH target'; remote_exec "test -f $(shell_quote "$PRODUCTION_ROOT/wp-config.php")" || die 4 'production wp-config.php is absent'; remote_exec "test -d $(shell_quote "$PRODUCTION_ROOT/wp-includes")" || die 4 'production root is not a WordPress installation'; REMOTE_HOME=$(normalize_url "$(remote_value option get home)") || die 4 'remote home URL malformed'; REMOTE_SITEURL=$(normalize_url "$(remote_value option get siteurl)") || die 4 'remote siteurl malformed'; [ "$REMOTE_HOME" = "$PRODUCTION_URL" ] || die 4 "remote home does not match production URL"; [ "$REMOTE_SITEURL" = "$PRODUCTION_URL" ] || die 4 "remote siteurl does not match production URL"; REMOTE_DB=$(remote_exec "cd $(shell_quote "$PRODUCTION_ROOT") && $REMOTE_WP_COMMAND db query 'SELECT DATABASE()' --skip-column-names" | tail -n1); [ "$REMOTE_DB" = "$PRODUCTION_EXPECTED_DB_NAME" ] || die 4 'remote database does not match PRODUCTION_EXPECTED_DB_NAME'; REMOTE_PREFIX=$(remote_value db prefix); [ -n "$REMOTE_PREFIX" ] || die 4 'remote table prefix is unavailable'; remote_exec "test -w $(shell_quote "$PRODUCTION_ROOT/wp-content/themes") && test -w $(shell_quote "$PRODUCTION_ROOT/wp-content/plugins") && test -w $(shell_quote "$PRODUCTION_ROOT/wp-content/uploads") && mkdir -p $(shell_quote "$REMOTE_BACKUP_ROOT") && test -w $(shell_quote "$REMOTE_BACKUP_ROOT")" || die 4 'production paths or backup root are not writable'; remote_exec 'command -v tar >/dev/null && command -v gzip >/dev/null' || die 4 'remote tar/gzip unavailable'; ok "verified production target $PRODUCTION_URL"; }
